#if UNITY_EDITOR
using System;using System.IO;using System.Linq;using System.Text;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;
namespace StarterAssets.CQCEditorTools {
[InitializeOnLoad] public static class InspectChapelDoors {
const string Request="Assets/Editor/CQC/InspectChapelDoors-v4.request.txt";static double next;
static InspectChapelDoors(){EditorApplication.update+=Poll;}
static void Poll(){if(EditorApplication.timeSinceStartup<next)return;next=EditorApplication.timeSinceStartup+2;if(!File.Exists(Request)||EditorApplication.isPlayingOrWillChangePlaymode||EditorApplication.isCompiling||EditorApplication.isUpdating)return;try{Apply();AssetDatabase.DeleteAsset(Request);}catch(Exception e){File.WriteAllText("Logs/ChapelDoors-error.txt",e.ToString());File.Move(Request,Request+".failed");}}
static void Apply(){var active=SceneManager.GetActiveScene();var main=SceneManager.GetSceneByPath("Assets/Scenes/MyForest.unity");bool opened=!main.isLoaded;if(opened)main=EditorSceneManager.OpenScene("Assets/Scenes/MyForest.unity",OpenSceneMode.Additive);var mountain=main.GetRootGameObjects().First(g=>g.name=="Castle Mountain");var church=mountain.transform.Find("Large Upper Castle Church");if(!church)return;var sb=new StringBuilder();sb.AppendLine("Church transform "+church.position+" rotation "+church.eulerAngles+" scale "+church.lossyScale);foreach(var r in church.GetComponentsInChildren<Renderer>())sb.AppendLine(r.name+" center "+r.bounds.center+" size "+r.bounds.size);
var portal=UnityEngine.Object.FindAnyObjectByType<ChapelThroneDomain>();if(portal)sb.AppendLine("Existing door "+(portal.ChapelDoor?portal.ChapelDoor.position.ToString():"MISSING")+" return "+(portal.OutsideReturn?portal.OutsideReturn.position.ToString():"MISSING"));
var preview=new PreviewRenderUtility();try{var clone=UnityEngine.Object.Instantiate(church.gameObject);clone.transform.position=Vector3.zero;preview.AddSingleGO(clone);var front=Vector3.ProjectOnPlane(-church.forward,Vector3.up).normalized;var target=new Vector3(0,6,0);foreach(var sign in new[]{1,-1}){preview.camera.transform.position=target+front*(sign*48)+Vector3.up*6;preview.camera.transform.LookAt(target+Vector3.up*3);preview.camera.fieldOfView=48;preview.camera.nearClipPlane=.1f;preview.camera.farClipPlane=200;preview.lights[0].intensity=2;preview.lights[0].transform.rotation=Quaternion.LookRotation(-front*sign+Vector3.down);preview.lights[1].intensity=1;FitSwordShoulder.Capture(preview,"Logs/ChapelDoors-"+(sign==1?"front":"back")+".png",clone);}}finally{preview.Cleanup();}File.WriteAllText("Logs/ChapelDoors-survey.txt",sb.ToString());if(opened){SceneManager.SetActiveScene(active);EditorSceneManager.CloseScene(main,true);}}
}}
#endif
